"""The 筆畫輸入法 (PIME) Service answers stroke input through the line protocol.

Each case instantiates the real service on the real Stroke table and drives it
the way the C++ client does: JSON requests in, reply dict out. Assertions
land on the reply dict and on the Candidate set the reply pages through
(CandidateView is that set's model, not a private detail). Expected
characters and stroke sequences are transcribed from the CNS11643 全字庫 open
data the table was derived from, not recomputed from the table itself
(CNS_strokes_sequence.txt joined to code points through CNS2UNICODE).
"""

import json
import os
import sys
import tempfile
import time
import unittest

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.path.pardir))
PYTHON_DIR = os.path.join(ROOT, "python")
TESTS_DIR = os.path.dirname(os.path.abspath(__file__))
for path in (PYTHON_DIR, TESTS_DIR):
    if path not in sys.path:
        sys.path.insert(0, path)

import ime_smoke_runner  # noqa: E402 - located after ROOT is known
ime_smoke_runner.install_windows_shims()

from keycodes import (  # noqa: E402
    VK_HOME, VK_NEXT, VK_OEM_3, VK_RIGHT, VK_SHIFT, VK_SPACE)

VK_8 = 0x38  # Shift+8 is the * wildcard key

# CNS 筆順 for the sampled characters, digits 1..5 = 橫豎撇點折:
# 二 11, 十 12, 万 135, 三 111, 土 121, 威 131531543 (second stroke 1/2/3
# across the wildcard). The digit-to-key mapping is the Five-stroke keyset.
CNS_DIGIT_TO_KEY = str.maketrans("12345", "hspnz")


def stroke_key(sequence):
    return sequence.translate(CNS_DIGIT_TO_KEY)


@unittest.skipIf(ime_smoke_runner.under_wine(),
                 "Wine lacks propsys.dll.VariantToString, which importing cinbase reaches")
@unittest.skipUnless(ime_smoke_runner.opencc_available(),
                     "libopencc is not installed")
class ChebihuaServiceTests(unittest.TestCase):
    def setUp(self):
        self.old_appdata = os.environ.get("APPDATA")
        self.old_cwd = os.getcwd()
        self.temp_dir = tempfile.TemporaryDirectory(prefix="pime-chebihua-")
        os.environ["APPDATA"] = self.temp_dir.name
        os.chdir(self.temp_dir.name)
        ime_smoke_runner.LAUNCHES.clear()

    def tearDown(self):
        os.chdir(self.old_cwd)
        if self.old_appdata is None:
            os.environ.pop("APPDATA", None)
        else:
            os.environ["APPDATA"] = self.old_appdata
        self.temp_dir.cleanup()

    @staticmethod
    def _request(service, method, char_code, key_code=None, shift=False, vk_down=()):
        event = dict(ime_smoke_runner.BASE_EVENT)
        event["keyStates"] = list(event["keyStates"])
        for vk in (VK_SHIFT if shift else None, *vk_down):
            if vk is not None:
                event["keyStates"][vk] = 0x80
        event.update(method=method, charCode=char_code,
                     keyCode=char_code if key_code is None else key_code, seqNum=1)
        return service.handleRequest(event)

    @staticmethod
    def press(service, char_code, key_code=None, shift=False, vk_down=()):
        """Filter first; let the service consume the key only if it claims it."""
        filtered = ChebihuaServiceTests._request(service, "filterKeyDown",
                                                 char_code, key_code, shift, vk_down)
        if not filtered.get("return"):
            return filtered
        return ChebihuaServiceTests._request(service, "onKeyDown",
                                             char_code, key_code, shift, vk_down)

    @staticmethod
    def force_press(service, char_code, key_code):
        """Filter and down, unconditionally.

        The `` ` `` menu is handled in onKeyDown alone, and press() stops early
        when the filter declines a key — which the arrow keys do. The real
        client sends both messages for every key, so this mirrors it.
        """
        ChebihuaServiceTests._request(service, "filterKeyDown", char_code, key_code)
        return ChebihuaServiceTests._request(service, "onKeyDown", char_code, key_code)

    def activate_chebihua(self):
        from input_methods.chebihua import chebihua_ime

        # Force a fresh table load so the Cin binds the APPDATA of this test.
        chebihua_ime.CinTable.cin = None
        chebihua_ime.CinTable.curCinType = None

        service = chebihua_ime.CheBihuaTextService(ime_smoke_runner.FakeClient())
        reply = service.handleRequest(
            {"method": "onActivate", "isKeyboardOpen": True, "seqNum": 1})
        self.assertTrue(reply.get("success"), reply)
        for _ in range(500):
            if chebihua_ime.CinTable.cin is not None and not chebihua_ime.CinTable.loading:
                break
            time.sleep(0.02)
        self.assertIsNotNone(chebihua_ime.CinTable.cin, "Stroke table never loaded")
        return service

    def type_strokes(self, service, *letters):
        reply = {}
        for letter in letters:
            reply = self.press(service, ord(letter))
        return reply

    def pages_surface(self, service, reply, char):
        """Whether the candidate window shows char on the current or a later page."""
        if char in (reply.get("candidateList") or []):
            return True
        for _ in range(service.candidateView.page_count):
            reply = self.press(service, 0, VK_NEXT)
            if char in (reply.get("candidateList") or []):
                return True
        return False

    def test_two_heng_strokes_offer_er_among_candidates(self):
        # CNS 筆順 of 二 is 11: the first page must already surface it.
        service = self.activate_chebihua()
        reply = self.type_strokes(service, "h", "h")
        self.assertIn("二", reply.get("candidateList") or [])

    def test_heng_shu_offers_shi_among_candidates(self):
        # CNS 筆順 of 十 is 12, so the strokes land on h then s.
        service = self.activate_chebihua()
        reply = self.type_strokes(service, "h", "s")
        self.assertTrue(self.pages_surface(service, reply, "十"),
                        "十 not in the hs candidate set")

    def test_heng_po_zhe_offers_wan_among_candidates(self):
        # CNS 筆順 of 万 is 135 (橫撇折), so the 折 key z closes the code.
        service = self.activate_chebihua()
        reply = self.type_strokes(service, "h", "p", "z")
        self.assertTrue(self.pages_surface(service, reply, "万"),
                        "万 not in the hpz candidate set")

    def test_composition_renders_stroke_glyphs_not_letters(self):
        service = self.activate_chebihua()
        reply = self.type_strokes(service, "h", "s", "p", "n", "z")
        self.assertEqual("一丨丿丶乙", reply.get("compositionString"))

    def test_wildcard_pattern_expands_across_stroke_classes(self):
        # h * h matches three-stroke codes 1?1: 三 111 (second 橫),
        # 土 121 (second 豎), 威 131531543 (second 撇, matched by its prefix).
        # The expansion is capped at candMaxItems; these three sit inside it.
        service = self.activate_chebihua()
        self.press(service, ord("h"))
        self.press(service, ord("*"), VK_8, shift=True)
        reply = self.press(service, ord("h"))
        self.assertEqual("一＊一", reply.get("compositionString"))
        candidates = service.candidateView.candidates
        self.assertIn("三", candidates)
        self.assertIn("土", candidates)
        self.assertIn("威", candidates)

    def test_non_root_letter_passes_through_when_idle(self):
        service = self.activate_chebihua()
        reply = self.press(service, ord("a"))
        self.assertFalse(reply.get("return"))
        self.assertEqual("", service.compositionString)

    def test_space_commits_highlighted_candidate_and_learns(self):
        service = self.activate_chebihua()
        reply = self.type_strokes(service, "h", "h")
        highlighted = (reply.get("candidateList") or [])[0]
        reply = self.press(service, VK_SPACE)
        self.assertEqual(highlighted, reply.get("commitString"))

        # Leaving the service flushes the usage counts it collected per code.
        service.handleRequest({"method": "onDeactivate", "seqNum": 2})
        count_file = os.path.join(self.temp_dir.name, "PIME", "chebihua",
                                  "cincount.json")
        with open(count_file, encoding="utf-8") as handle:
            counts = json.load(handle)
        self.assertGreaterEqual(counts[stroke_key("11")][highlighted]["count"], 1)

    def test_no_phrase_candidates_after_commit(self):
        # 聯想字 ships off: committing must not enter phrase mode, and the
        # next stroke must open a fresh composition instead.
        service = self.activate_chebihua()
        self.type_strokes(service, "h", "h")
        reply = self.press(service, VK_SPACE)
        self.assertFalse(reply.get("showCandidates"))
        reply = self.press(service, ord("h"))
        self.assertEqual("一", reply.get("compositionString"))

    def test_learning_can_be_toggled_off_from_the_function_menu(self):
        # The 功能開關 menu is how a user turns the shipped-on learning counts
        # off, so the switch has to be reached the way a user reaches it: `` ` ``
        # opens the menu, the arrows walk the candidate view, Space picks the
        # highlighted item. Picking 功能開關 moves to that page, and picking
        # 智慧選字 is what the engine answers with onMenuCommand(i, 1).
        #
        # This used to press `` ` `` and then dispatch
        # onCommand(smenuitems.index("intelligentSelect"), 1) — but the line
        # protocol has no menu command (textService.py maps "onCommand" to
        # onCommand alone, whose ids are the language-bar constants), so the
        # index 6 landed on ID_BUGREPORT and opened
        # https://github.com/EasyIME/PIME/issues, while the Space below picked
        # 功能設定, the item still highlighted in the menu the test had opened,
        # and ShellExecuteW'd the settings tool. The count-file assertion below
        # then passed because nothing had ever been committed, not because the
        # switch worked.
        service = self.activate_chebihua()
        self.assertTrue(service.intelligentSelect, "智慧選字 ships on")

        # `` ` `` then Shift+M composes the composition string the 功能選單 opens
        # on (python/cinbase/__init__.py:718) — the only route a user has.
        self.press(service, ord("`"), VK_OEM_3, vk_down=(VK_OEM_3,))
        self.press(service, ord("M"), shift=True)
        # smenuitems and smenucandidates are filled as the menu opens, in parallel.
        self.assertIn("intelligentSelect", service.smenuitems)
        self.assertEqual(0, service.menutype, "the 功能選單 did not open")

        for _ in range(service.candidateList.index("功能開關")):
            self.force_press(service, 0, VK_RIGHT)
        self.assertEqual("功能開關", service.candidateList[service.candidateView.cursor])
        self.force_press(service, VK_SPACE, VK_SPACE)
        self.assertEqual(1, service.menutype, "the 功能開關 page did not open")

        index = service.smenuitems.index("intelligentSelect")
        self.force_press(service, 0, VK_HOME)
        for _ in range(index):
            self.force_press(service, 0, VK_RIGHT)
        self.force_press(service, VK_SPACE, VK_SPACE)
        self.assertFalse(service.intelligentSelect,
                         "智慧選字 stayed on after being picked from the menu")
        self.assertEqual([], ime_smoke_runner.LAUNCHES,
                         "the menu route reached the desktop")

        service.handleRequest({"method": "onCompositionTerminated",
                               "forced": True, "seqNum": 3})
        reply = self.type_strokes(service, "h", "h")
        self.assertTrue(reply.get("candidateList"))
        self.press(service, VK_SPACE)
        service.handleRequest({"method": "onDeactivate", "seqNum": 4})
        count_file = os.path.join(self.temp_dir.name, "PIME", "chebihua",
                                  "cincount.json")
        self.assertFalse(os.path.exists(count_file),
                         "counts kept accumulating after 智慧選字 was turned off")


